package dev.shiye.app;
import android.content.*;import android.os.*;import java.io.File;
final class MainActivity extends ContextWrapper {final Handler main=new Handler(Looper.getMainLooper());final LocalStore store;final String run;MainActivity(Context c,String id)throws Exception{super(c);run=id;store=new LocalStore(this);} @Override public Context getApplicationContext(){return this;} @Override public SharedPreferences getSharedPreferences(String n,int m){return super.getSharedPreferences(run+"-"+n,m);} @Override public File getDatabasePath(String n){return super.getDatabasePath(run+"-"+n);} @Override public File getFilesDir(){File p=new File(super.getFilesDir(),run);p.mkdirs();return p;} @Override public File getNoBackupFilesDir(){File p=new File(super.getNoBackupFilesDir(),run);p.mkdirs();return p;} }
